function buildAccessNotice(state) {
  if (state === null || typeof state !== 'object' || Array.isArray(state)) {
    throw new TypeError('Expected a state record');
  }
  const keys = Object.keys(state);
  if (keys.length !== 3 || !keys.includes('signedIn') || !keys.includes('fault') || !keys.includes('displayName')) {
    throw new TypeError('Unexpected state shape');
  }
  if (typeof state.signedIn !== 'boolean' || typeof state.fault !== 'boolean' || typeof state.displayName !== 'string') {
    throw new TypeError('Invalid state values');
  }

  if (!state.signedIn) {
    return { message: 'Hello, visitor', actions: ['sign-in'] };
  }
  if (state.fault) {
    return { message: 'Service unavailable', actions: ['retry'] };
  }
  const name = state.displayName.trim();
  if (name.length === 0) throw new RangeError('Display name is empty');
  return { message: `Hello again, ${name}`, actions: ['sign-out'] };
}

module.exports = { buildAccessNotice };

