'use strict';
const assert = require('node:assert/strict');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['buildAccessNotice']);
const { buildAccessNotice } = api;
assert.equal(typeof buildAccessNotice, 'function');

const faultInput = Object.freeze({ signedIn: true, fault: true, displayName: '' });
const faultNotice = buildAccessNotice(faultInput);
assert.deepStrictEqual(faultNotice, { message: 'Service unavailable', actions: ['retry'] });
assert.deepStrictEqual(faultInput, { signedIn: true, fault: true, displayName: '' });
assert.deepStrictEqual(
  buildAccessNotice({ signedIn: false, fault: true, displayName: 'Anyone' }),
  { message: 'Service unavailable', actions: ['retry'] }
);

const visitor = buildAccessNotice(Object.freeze({ signedIn: false, fault: false, displayName: '' }));
assert.deepStrictEqual(visitor, { message: 'Hello, visitor', actions: ['sign-in'] });
assert.deepStrictEqual(
  buildAccessNotice({ signedIn: false, fault: false, displayName: '   ' }),
  { message: 'Hello, visitor', actions: ['sign-in'] }
);

const signedInInput = Object.freeze({ signedIn: true, fault: false, displayName: '  Ada Lovelace  ' });
const welcome = buildAccessNotice(signedInInput);
assert.deepStrictEqual(welcome, { message: 'Hello again, Ada Lovelace', actions: ['sign-out'] });
assert.deepStrictEqual(signedInInput, { signedIn: true, fault: false, displayName: '  Ada Lovelace  ' });

const welcomeAgain = buildAccessNotice(signedInInput);
assert.notStrictEqual(welcomeAgain, welcome);
assert.notStrictEqual(welcomeAgain.actions, welcome.actions);
welcome.actions.push('tamper');
assert.deepStrictEqual(welcomeAgain.actions, ['sign-out']);

for (const bad of [null, [], undefined, 'x', 0, true]) {
  assert.throws(() => buildAccessNotice(bad), TypeError);
}
for (const bad of [
  {},
  { signedIn: true, fault: false },
  { signedIn: true, fault: false, displayName: 'Ada', extra: true },
  { signedIn: 1, fault: false, displayName: 'Ada' },
  { signedIn: true, fault: 0, displayName: 'Ada' },
  { signedIn: true, fault: false, displayName: null }
]) assert.throws(() => buildAccessNotice(bad), TypeError);

assert.throws(
  () => buildAccessNotice({ signedIn: true, fault: false, displayName: '' }),
  RangeError
);
assert.throws(
  () => buildAccessNotice({ signedIn: true, fault: false, displayName: ' \t\n ' }),
  RangeError
);

